<?php
namespace App\Http\Controllers;
use App\Actions\Inspections\AssignInspectionResponsible;use App\Http\Requests\Inspections\AssignResponsibleRequest;use App\Models\{Inspection,InspectionResponsible};use Illuminate\Http\{RedirectResponse,Request};
final class InspectionResponsibleController extends Controller {public function store(AssignResponsibleRequest $r,Inspection $inspection,AssignInspectionResponsible $a):RedirectResponse{$i=$this->tenant($r,$inspection);$this->authorize('assignResponsibles',$i);$a->handle($i,(int)$r->user()->id,$r->validated());return back();}public function update(AssignResponsibleRequest $r,Inspection $inspection,InspectionResponsible $responsible,AssignInspectionResponsible $a):RedirectResponse{$i=$this->tenant($r,$inspection);$this->related($i,$responsible);$this->authorize('assignResponsibles',$i);$responsible->delete();$a->handle($i,(int)$r->user()->id,$r->validated());return back();}public function destroy(Request $r,Inspection $inspection,InspectionResponsible $responsible):RedirectResponse{$i=$this->tenant($r,$inspection);$this->related($i,$responsible);$this->authorize('assignResponsibles',$i);$responsible->delete();return back();}private function tenant(Request $r,Inspection $i):Inspection{abort_unless((int)$i->organization_id===(int)$r->user()->organization_id,404);return $i;}private function related(Inspection $i,InspectionResponsible $v):void{abort_unless((int)$v->inspection_id===(int)$i->id&&(int)$v->organization_id===(int)$i->organization_id,404);}}
